        DB::transaction(function () use ($templates, $userId) {
            $templateNames = array_map(fn ($t) => $t['template'], $templates);

            $existing = TemplateRoute::whereIn('template', $templateNames)
                ->get()
                ->keyBy('template');

            foreach ($templates as $tpl) {
                $template = $tpl['template'];
                $payload = [
                    'template' => $template,
                    'user_id' => $userId,
                    'metadata' => $tpl['metadata'],
                    'wod_ref' => $tpl['wod_ref'],
                ];

                if ($existing->has($template)) {
                    // Keep existing UUID; just update metadata and WO refs
                    $existing->get($template)->update($payload);
                } else {
                    $payload['uuid'] = (string) Str::uuid();
                    TemplateRoute::create($payload);
                }
            }
        });
